(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory(require('./timezone.js'));else root.OrbitSchedule=factory(OrbitTime);})(globalThis,function(time){
 function zoomLink(event){const text=[event.zoomLink,event.location,event.notes,event.description,event.conferenceData?.entryPoints?.map(p=>p.uri).join(' ')].filter(Boolean).join(' ').replaceAll('&amp;','&');for(const candidate of text.match(/https:\/\/[a-zA-Z0-9.-]+\/(?:j|my|wc\/join)\/[^\s<>"']+/g)||[]){try{const u=new URL(candidate.replace(/[.,;，。；)]+$/,''));if(u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&(u.hostname==='zoom.us'||u.hostname.endsWith('.zoom.us')||u.hostname==='zoom.com'||u.hostname.endsWith('.zoom.com'))&&/^\/(?:j|my|wc\/join)\/[^/]+\/?$/.test(u.pathname))return u.href;}catch{}}return '';}
 function start(event,zone){if(event.allDay)return null;const value=Date.parse(event.startAt);if(Number.isFinite(value))return value;try{return Date.parse(time.localInstant(event.date,event.time,zone));}catch{return null;}}
 function ended(event,zone,now=Date.now()){if(event.allDay)return !!event.date&&event.date<time.dateKey(now,zone);const at=start(event,zone);return at!==null&&at+Math.max(0,Number(event.duration)||0)*60000<=now;}
 function merge(...groups){const result=new Map();for(const event of groups.flat()){const key=event.identity||event.id;if(!key)continue;const old=result.get(key);result.set(key,{...old,...event,zoomLink:zoomLink(event)||old?.zoomLink||''});}return [...result.values()].sort((a,b)=>(a.startAt||a.date+'T'+a.time).localeCompare(b.startAt||b.date+'T'+b.time));}
 return {zoomLink,start,ended,merge};
});
